    val m = Array(10000005) { Div3(0L, 0L, 0L) }
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val buffer = reader.readLine()

    val st = StringTokenizer(buffer)
    val x = LongArray(3)
    var idx = 0
    while (st.hasMoreTokens()) {
        x[idx++] = st.nextToken().toLong()
    }

    val d = (x[2] - x[1] + 1) / 3
    val moder = 1_000_000_007L

    var nums = Div3(
        remain0 = d,
        remain1 = d,
        remain2 = d
    )

    if ((x[2] - x[1] + 1) % 3 > 0) {
        val t = if ((x[2] - x[1] + 1) % 3 == 2L) 1L else 0L
