            nums.remain0 = nums.remain0 + 1
            nums.remain1 = nums.remain1 + t
        } else if (x[1] % 3 == 1L) {
            nums.remain1 = nums.remain1 + 1
            nums.remain2 = nums.remain2 + t
        } else {
            nums.remain2 = nums.remain2 + 1
            nums.remain0 = nums.remain0 + t
        }
    }

