    var i = 2L
    while (i < x[0] + 1) {
        val it = i.toInt()
        val prev = m[it - 1]
        val cur = m[it]
        cur.remain0 = ((prev.remain0 * nums.remain0) % moder +
                (prev.remain1 * nums.remain2) % moder +
                (prev.remain2 * nums.remain1) % moder) % moder
        cur.remain1 = ((prev.remain1 * nums.remain0) % moder +
                (prev.remain0 * nums.remain1) % moder +
                (prev.remain2 * nums.remain2) % moder) % moder
